#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using UnityEngine;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.krakenDrainageSplash)]
    public class KrakenDrainageSplash : EntityBehaviourDefinition, IBeFrozenBehaviour
    {
        public KrakenDrainageSplash(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.SetTint(entity.Level.GetWaterColor());
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            entity.SetAnimationBool("Stopped", IsStopped(entity));
        }

        public void BeFrozen(Entity entity, Entity source)
        {
            if (IsStopped(entity))
                return;
            entity.Spawn(VanillaEffectID.risingIcePillar, entity.Position);
            entity.Remove();
        }
        public static void Stop(Entity entity)
        {
            entity.Timeout = Mathf.Min(entity.Timeout, STOP_TIMEOUT);
        }
        public static bool IsStopped(Entity entity)
        {
            return entity.Timeout <= STOP_TIMEOUT;
        }
        public const int STOP_TIMEOUT = 30;
    }
}